 private void categoryGrid(TreeSet<String> names,String field,boolean companies){LinearLayout row=null;int index=0;for(String name:names){if(!query.isEmpty()&&!(companies?companyQuery(name):name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT))))continue;int count=0,unread=0;for(int i=0;i<docs.length();i++)if(companies?companyMember(docs.optJSONObject(i),name):contains(docs.optJSONObject(i).optJSONArray(field),name)){count++;if(!prefs.getBoolean("read:"+docs.optJSONObject(i).optString("document_id"),false))unread++;}if(index%2==0){row=new LinearLayout(this);content.addView(row);}Button b=button((companies&&companyIsFollowed(name)?"★ ":"")+(companies?companyLabel(name):name)+"\n"+count+" 篇 · "+unread+" 未读",()->{if(companies)company=name;else industry=name;render();});b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setBackground(surface(Color.WHITE,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);b.setMinHeight(dp(68));lp.setMargins(dp(3),dp(5),dp(3),dp(5));row.addView(b,lp);index++;}if(index%2==1)row.addView(new View(this),new LinearLayout.LayoutParams(0,dp(68),1));}
 private boolean contains(JSONArray values,String value){if(values==null)return false;for(int i=0;i<values.length();i++)if(values.optString(i).equals(value))return true;return false;}
